"use client";

import { useRef } from "react";
import { useScroll } from "framer-motion";
import HeroCanvas from "./HeroCanvas";
import HeroTextOverlays from "./HeroTextOverlays";
import "@/styles/hero.css";

export default function Hero() {
  const containerRef = useRef<HTMLDivElement>(null);

  // We track the scroll progress of the entire tall container.
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  return (
    <section 
      ref={containerRef} 
      className="relative w-full h-[500vh] bg-[#001827]"
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">
        {/* The background canvas animation */}
        {/* Adjusted totalFrames to match the exact number of frames in imagesf directory */}
        <HeroCanvas scrollYProgress={scrollYProgress} totalFrames={240} />
        
        {/* The cornered text overlays synced to the scroll */}
        <HeroTextOverlays scrollYProgress={scrollYProgress} />
      </div>
    </section>
  );
}
